package terminal

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// Exercise the real Windows console mode, input records and picker together.
// ConPTY sends exactly the sequences generated by Windows Terminal arrow keys.
func TestWindowsPickerArrowKeys(t *testing.T) {
	for _, tc := range []struct {
		name, input, want string
		cancelled         bool
	}{
		{"down", "\x1b[B\r", "beta", false},
		{"down then up", "\x1b[B\x1b[A\r", "alpha", false},
		{"filter arrows", "/item\x1b[B\x1b[A\x1b[B\r", "beta", false},
		{"application arrows", "\x1bOB\r", "beta", false},
		{"q exits", "q", "", true},
		{"q filters", "/q\r", "beta", false},
		{"q after filter closes", "/q", "", true},
		{"escape exits", "\x1b", "", true},
		{"ctrl c exits", "\x03", "", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			exe, err := os.Executable()
			if err != nil {
				t.Fatal(err)
			}
			resultFile := filepath.Join(t.TempDir(), "result.json")
			r, err := Start(Options{Executable: exe, Args: []string{"-test.run=^$"},
				Dir: t.TempDir(), Cols: 100, Rows: 24,
				Env: append(CleanEnv(os.Environ()), "CC_REMOTE_PICKER_CHILD=1", "CC_REMOTE_PICKER_RESULT="+resultFile)})
			if err != nil {
				t.Fatal(err)
			}
			t.Cleanup(func() { r.Close(time.Second) })
			sub := r.Subscribe()
			var seen strings.Builder
			collect(t, sub, &seen, "item Alpha")
			// Write directly to ConPTY so the Claude runner's readiness gate is irrelevant.
			input := tc.input
			if !tc.cancelled {
				input += "\x03" // Stop a broken selection without waiting for the timeout.
			}
			if _, err := r.pty.Write([]byte(input)); err != nil {
				t.Fatal(err)
			}
			if tc.name == "q after filter closes" {
				// ESC immediately followed by q is Alt+q to the ConPTY decoder.
				// Wait for each render to exercise separate Escape and q presses.
				seen.Reset()
				collect(t, sub, &seen, "/ q")
				if _, err := r.pty.Write([]byte("\x1b")); err != nil {
					t.Fatal(err)
				}
				seen.Reset()
				collect(t, sub, &seen, "q/Esc")
				if _, err := r.pty.Write([]byte("q")); err != nil {
					t.Fatal(err)
				}
			}
			select {
			case <-r.Done():
			case <-time.After(5 * time.Second):
				t.Fatal("picker did not consume arrow/Enter input")
			}
			data, err := os.ReadFile(resultFile)
			if err != nil {
				t.Fatal(err)
			}
			var result pickerTestResult
			if err := json.Unmarshal(data, &result); err != nil {
				t.Fatal(err)
			}
			wantError := ""
			if tc.cancelled {
				wantError = errPickerCancelled.Error()
			}
			if result.ID != tc.want || result.Error != wantError || !result.ModeRestored {
				t.Fatalf("arrow selection: got %+v, want %s; initial output %q", result, tc.want, seen.String())
			}
		})
	}
}
